    tempRoot: join(runtimeRoot, "tmp"),
    cacheRoot: join(runtimeRoot, "cache"),
    configRoot: join(runtimeRoot, "config"),
    dataRoot: join(runtimeRoot, "data"),
    descriptorPath: join(runtimeRoot, "session.json"),
